INSERT INTO USERS (
    user_id, user_email, user_password, password_enabled,
    email_verified, email_login_enabled, account_status, user_role,
    nickname, nationality, preferred_lang
) VALUES (
    #{userId}, #{userEmail}, #{userPassword}, #{passwordEnabled},
    false, false, 'ACTIVE', 'USER',
    #{nickname}, #{nationality}, #{preferredLang}
)

mapper.update:
UPDATE USERS
SET nickname      = #{nickname},
    nationality   = #{nationality},
    preferred_lang= #{preferredLang}
WHERE user_idx = #{userIdx}

UPDATE USERS
SET user_id = #{userId}
WHERE user_idx = #{userIdx}
  AND user_id IS NULL

UPDATE USERS
SET email_verified = #{emailVerified}
WHERE user_idx = #{userIdx}

UPDATE USERS
SET email_login_enabled = #{enabled}
WHERE user_idx = #{userIdx}
  AND email_verified = TRUE

